import type { LearnTopic } from './types';

// Generated by scripts/diary-import/build_learn.py from the Ly_thuyet sheet. General nutrition knowledge, not medical advice.
export const LEARN_TOPICS: LearnTopic[] = [
  { id: 1, section: 'basics', title: 'Nguyên lý giảm mỡ: cân bằng năng lượng', evidence: 'strong', points: ['Mỡ chỉ giảm khi năng lượng ăn vào thấp hơn năng lượng cơ thể tiêu hao (TDEE) trong một khoảng thời gian đủ dài.', 'TDEE gồm 4 phần: chuyển hóa cơ bản BMR (~60–70%, năng lượng để sống), sinh nhiệt khi tiêu hóa TEF (~10%), vận động đời thường NEAT (đi lại, đứng, làm việc nhà) và tập luyện có chủ đích.', 'Khi thiếu năng lượng, cơ thể lấy phần thiếu từ kho dự trữ – chủ yếu là mỡ, nhưng cũng có thể lấy cả cơ nếu ăn thiếu đạm và không vận động.', 'Khi nhẹ cân đi, TDEE giảm theo (cơ thể nhỏ hơn tốn ít năng lượng hơn), nên mức ăn cũ sẽ tạo thâm hụt nhỏ dần – đó là lý do giảm cân chậm lại theo thời gian.'] },
  { id: 2, section: 'basics', title: 'Cơ chế đốt mỡ trong cơ thể', evidence: 'strong', points: ['Mỡ được cất trong tế bào mỡ dưới dạng triglyceride.', 'Khi insulin thấp (xa bữa ăn, ít đường) và cơ thể cần năng lượng, hormone (adrenaline, glucagon) kích hoạt enzyme phân giải mỡ → tách triglyceride thành axit béo + glycerol.', 'Axit béo theo máu đến cơ, gan; vào ty thể để \'đốt\' (beta-oxy hóa) tạo năng lượng. Glycerol được gan dùng tạo đường.', 'Sản phẩm cuối là CO₂ và nước: phần lớn khối lượng mỡ mất đi được thở ra dưới dạng CO₂, phần còn lại thải qua nước tiểu, mồ hôi.', 'Không thể \'đốt mỡ tại chỗ\' (gập bụng không đốt riêng mỡ bụng); mỡ giảm toàn thân theo thứ tự do gen quyết định.'] },
  { id: 3, section: 'basics', title: 'Vì sao cân lên xuống thất thường từng ngày', evidence: 'strong', points: ['Cân nặng = mỡ + cơ + nước + glycogen + thức ăn trong ruột. Mỡ thay đổi chậm, còn nước có thể dao động 1–2 kg chỉ sau một ngày.', 'Muối: ăn mặn làm cơ thể giữ nước để pha loãng natri → cân tăng 0.5–2 kg dù không tăng mỡ.', 'Glycogen: mỗi 1 g tinh bột dự trữ trong cơ/gan giữ kèm ~3 g nước; ăn nhiều tinh bột → cân tăng, siết tinh bột → cân tụt nhanh (chủ yếu là nước).', 'Vì vậy cần nhìn xu hướng nhiều lần cân, không nhìn một con số.'] },
  { id: 4, section: 'food', title: 'Vì sao cần kiêng đường (đường thêm vào)', evidence: 'strong', points: ['Đường thêm vào (trà sữa, nước ngọt, bánh kẹo, sốt ướp) là calo \'rỗng\': nhiều năng lượng, gần như không làm no, dễ uống/ăn vượt mức.', 'Đường làm insulin tăng cao – khi insulin cao, cơ thể ưu tiên cất năng lượng và tạm dừng phân giải mỡ.', 'Đường huyết lên nhanh rồi xuống nhanh → đói lại sớm, thèm ngọt tiếp.', 'Riêng với GOUT: fructose (có trong đường kính, siro, nước ngọt, nước ép) khi chuyển hóa ở gan làm tăng sản sinh axit uric trực tiếp. Đồ uống có đường gắn với nguy cơ gout cao hơn rõ rệt.'] },
  { id: 5, section: 'food', title: 'Vì sao hạn chế da, mỡ động vật, dầu ăn', evidence: 'strong', points: ['Chất béo có 9 kcal/g, gấp hơn 2 lần đạm và tinh bột (4 kcal/g). 1 thìa canh dầu ≈ 120 kcal – đổ mạnh tay khi xào/chiên có thể thêm 200–400 kcal mà không nhận ra.', 'Da gà/vịt/ngan chủ yếu là mỡ: bỏ da tiết kiệm 50–100 kcal mỗi miếng.', 'Đồ chiên ngập dầu hút nhiều dầu và thường mặn → vừa nhiều calo vừa giữ nước.', 'Không phải bỏ hết chất béo: cơ thể vẫn cần chất béo tốt (cá, hạt, dầu oliu, bơ quả) với lượng vừa phải để hấp thu vitamin và tạo hormone.'] },
  { id: 6, section: 'food', title: 'Vì sao cần giảm muối (natri)', evidence: 'strong', points: ['Natri cao làm cơ thể giữ nước → cân tăng ảo, phù nhẹ, khó đọc tiến độ.', 'Lâu dài làm tăng huyết áp, tăng gánh nặng cho thận và tim.', 'Đồ mặn (snack, chả, xúc xích, mì gói, nước chấm) thường đi kèm nhiều calo và kích thích ăn thêm.', 'Natri chủ yếu đến từ đồ chế biến sẵn và nước chấm, không phải từ muối bạn tự nêm.'] },
  { id: 7, section: 'food', title: 'Vì sao nên ăn đủ protein', evidence: 'strong', points: ['No lâu nhất trong các chất: đạm làm tăng hormone no và giảm hormone đói.', 'Hiệu ứng sinh nhiệt cao: cơ thể tiêu tốn ~20–30% năng lượng của đạm chỉ để tiêu hóa nó (tinh bột ~5–10%, chất béo ~0–3%).', 'Giữ cơ khi đang thâm hụt: thiếu đạm, cơ thể sẽ lấy cơ làm năng lượng → mất cơ → TDEE giảm → giảm cân khó hơn và dễ tăng lại.', 'Hỗ trợ phục hồi dây chằng, khớp sau tập.', 'Với GOUT cần chọn nguồn đạm ít purine: lòng trắng trứng, trứng, sữa/sữa chua ít béo (sữa còn hỗ trợ thải axit uric), đậu phụ; hạn chế nội tạng, hải sản có vỏ, cá nhỏ ăn cả con, thịt đỏ nhiều.'] },
  { id: 8, section: 'food', title: 'Vì sao ăn theo thứ tự: rau → đạm → tinh bột', evidence: 'medium', points: ['Chất xơ trong rau tạo lớp \'lưới\' trong dạ dày, làm chậm tốc độ thức ăn xuống ruột.', 'Đạm và chất béo ăn trước kích thích hormone no (GLP-1) và làm dạ dày rỗng chậm hơn.', 'Khi tinh bột đến sau, đường được hấp thu từ từ → đường huyết và insulin tăng ít hơn, ít buồn ngủ sau ăn, no lâu hơn.', 'Ăn rau trước cũng chiếm chỗ trong dạ dày nên tự nhiên ăn ít tinh bột hơn.'] },
  { id: 9, section: 'food', title: 'Vì sao ưu tiên carb no lâu (gạo lứt, yến mạch, khoai lang, miến dong)', evidence: 'medium', points: ['Có nhiều chất xơ hơn tinh bột tinh chế (cơm trắng, bánh mì trắng, bún phở, mì gói) → tiêu hóa chậm, đường huyết lên từ từ.', 'Yến mạch có beta-glucan tạo gel trong ruột, giúp no lâu và hỗ trợ giảm mỡ máu.', 'Nhiều chất xơ giúp nhai lâu hơn, ăn chậm hơn → tín hiệu no kịp đến.', 'Vẫn là tinh bột: no lâu không có nghĩa là ăn bao nhiêu cũng được – vẫn cần cân lượng.'] },
  { id: 10, section: 'food', title: 'Vì sao lòng trắng trứng tốt cho giảm cân (và cho gout)', evidence: 'strong', points: ['100 g lòng trắng ≈ 50 kcal, 11 g đạm, gần như 0 chất béo và gần như 0 purine.', 'Là một trong những nguồn đạm \'rẻ calo\' nhất → dễ đạt 110 g đạm mà vẫn giữ thâm hụt.', 'Giá trị sinh học cao, dễ tiêu hóa, dễ biến tấu (rán không dầu, hấp, nấu canh).', 'Lòng đỏ không xấu: có vitamin, chất béo tốt – chỉ là nhiều calo hơn (~55 kcal/lòng đỏ).'] },
  { id: 11, section: 'food', title: 'Vì sao nước chanh hỗ trợ', evidence: 'limited', points: ['Tác dụng chính là gián tiếp: giúp uống nhiều nước hơn và thay thế nước ngọt (gần 0 kcal nếu không đường).', 'Chanh có citrate, có thể giúp nước tiểu bớt axit – môi trường thuận lợi hơn cho thải axit uric và giảm nguy cơ sỏi thận.', 'Vitamin C ở liều cao đều đặn có liên quan đến axit uric thấp hơn một chút.', 'Bản thân chanh không \'đốt mỡ\'.'] },
  { id: 12, section: 'food', title: 'Vì sao giấm táo có thể hỗ trợ', evidence: 'limited', points: ['Axit axetic có thể làm dạ dày rỗng chậm hơn và giảm nhẹ đường huyết sau bữa nhiều tinh bột → no lâu hơn một chút.', 'Tác dụng lên cân nặng trong các nghiên cứu khá nhỏ (khoảng 1–2 kg sau vài tháng) – là phần phụ, không thay thế thâm hụt calo.', 'Có thể gây xót dạ dày, trào ngược, mòn men răng nếu uống đặc hoặc lúc đói.'] },
  { id: 13, section: 'food', title: 'Vì sao nên uống cà phê đen / americano', evidence: 'medium', points: ['Gần 0 kcal (so với cà phê sữa đá, latte, cacao 150–400 kcal).', 'Caffeine làm giảm cảm giác đói tạm thời và tăng nhẹ năng lượng tiêu hao, giúp tỉnh táo để vận động nhiều hơn.', 'Với GOUT: uống cà phê đều đặn có liên quan đến mức axit uric thấp hơn và nguy cơ cơn gout thấp hơn.', 'Lưu ý: không uống sau ~14–15h (ảnh hưởng giấc ngủ → tăng thèm ăn hôm sau); dạ dày nhạy cảm thì uống sau ăn; tối đa ~3–4 cốc/ngày.'] },
  { id: 14, section: 'food', title: 'Vì sao cần uống đủ và nhiều nước mỗi ngày', evidence: 'strong', points: ['Axit uric được thải chủ yếu qua thận: nhiều nước tiểu hơn → thải được nhiều axit uric hơn, giảm nguy cơ tinh thể urat và sỏi thận.', 'Thiếu nước làm máu cô đặc → axit uric trong máu tăng → dễ khởi phát cơn gout.', 'Giúp thải bớt natri sau bữa mặn, giảm tích nước.', 'Cảm giác khát hay bị nhầm thành đói; uống 1–2 cốc nước trước bữa giúp ăn ít hơn.', 'Tham khảo: ~2.5–3 lít/ngày (nước tiểu vàng nhạt là ổn), uống rải đều, thêm khi tập/trời nóng. Không uống ồ ạt vài lít trong thời gian ngắn. Nếu bác sĩ yêu cầu hạn chế nước (bệnh thận/tim) thì theo bác sĩ.'] },
  { id: 15, section: 'habit', title: 'Vì sao nên tự nấu ăn ở nhà thay vì mua/ăn ngoài', evidence: 'medium', points: ['Kiểm soát được dầu, muối, đường – 3 thứ quán thường dùng nhiều để món ngon hơn.', 'Kiểm soát khẩu phần (quán thường cho nhiều tinh bột, ít rau).', 'Ghi chép chính xác hơn: món tự nấu biết rõ gram, món ngoài chỉ ước lượng và thường bị ước THẤP.', 'Chọn được nguyên liệu ít purine, ít chế biến sẵn.'] },
  { id: 16, section: 'habit', title: 'Vì sao nên lắng nghe cơ thể, không ăn theo thói quen hay vì \'còn dư kcal\'', evidence: 'medium', points: ['Ngân sách calo là giới hạn trên, không phải chỉ tiêu phải ăn hết. Không đói mà vẫn ăn cho \'đủ số\' là bỏ phí thâm hụt.', 'Tín hiệu no cần ~15–20 phút mới đến não → ăn chậm, dừng khi no ~80%.', 'Phân biệt đói thật (đến từ từ, ăn gì cũng được) với thèm (đến đột ngột, thèm một món cụ thể, thường do buồn chán/căng thẳng/thói quen giờ giấc).', 'Ăn phần thừa \'cho khỏi phí\' là kiểu ăn theo thói quen phổ biến nhất.'] },
  { id: 17, section: 'habit', title: 'Stress ảnh hưởng thế nào đến giảm cân và gout', evidence: 'medium', points: ['Khi căng thẳng, cơ thể tiết cortisol và adrenaline. Ngắn hạn thì có lợi (tỉnh táo), nhưng stress kéo dài giữ cortisol cao liên tục.', 'Cortisol cao: tăng thèm đồ ngọt, béo, mặn (não tìm \'phần thưởng\' nhanh); ưu tiên tích mỡ vùng bụng; làm cơ thể giữ natri và nước → cân tăng ảo.', 'Stress làm ngủ kém → vòng lặp: ngủ kém → thèm ăn → ăn quá → tự trách → stress hơn.', 'Ăn uống quá khắt khe cũng là một dạng stress: cảm giác thiếu thốn kéo dài dễ dẫn đến \'vỡ trận\' ăn bù.', 'Stress tâm lý và thể chất (thiếu ngủ, làm việc căng) là một trong các yếu tố có thể kích hoạt cơn gout.', 'Cách giảm: đi bộ 10–20 phút ngoài trời; thở chậm 4–6 (hít 4 giây, thở ra 6 giây) trong 3–5 phút; tách công việc khỏi bữa ăn; 80/20 thay cho \'cấm tuyệt đối\'; nhìn tiến độ theo tuần thay vì từng ngày.'] },
  { id: 18, section: 'habit', title: 'Giấc ngủ hiệu quả – \'bài tập\' bị bỏ quên', evidence: 'strong', points: ['Thiếu ngủ (< 6–7 giờ) làm tăng ghrelin (hormone đói) và giảm leptin (hormone no) → hôm sau thường ăn thêm vài trăm kcal, thèm đồ ngọt/tinh bột rõ rệt.', 'Ngủ thiếu làm giảm độ nhạy insulin, tăng cortisol và khi đang thâm hụt calo thì cơ thể mất cơ nhiều hơn, mất mỡ ít hơn.', 'Ngủ kém làm giảm ý chí và năng lượng → ít vận động (NEAT giảm) → TDEE thực tế giảm mà không nhận ra.', 'Ngủ ngáy to, ngưng thở khi ngủ phổ biến ở người > 100 kg, làm giấc ngủ kém chất lượng dù ngủ đủ giờ – và có liên quan đến axit uric cao. Nếu hay ngáy to, mệt khi thức dậy, buồn ngủ ban ngày → nên khám.', 'Ngủ hiệu quả: 7–8 giờ; giờ ngủ/thức cố định (kể cả cuối tuần lệch ≤ 1 giờ); không cà phê sau 14–15h; bữa tối xong trước giờ ngủ 2–3 giờ (dạ dày nhạy cảm, tránh trào ngược); tắt màn hình 30–60 phút trước ngủ; phòng tối, mát; hạn chế rượu (rượu làm ngủ nông, và làm tăng axit uric).'] },
  { id: 19, section: 'habit', title: 'Cách giảm cơn thèm ăn', evidence: 'medium', points: ['Ăn đủ đạm và rau ở mỗi bữa chính – nguyên nhân phổ biến nhất của thèm vặt là bữa chính thiếu đạm/chất xơ.', 'Không bỏ bữa rồi ăn bù: đói quá mức dễ dẫn đến ăn mất kiểm soát.', 'Uống 1 cốc nước hoặc trà nóng, chờ 10–15 phút; cơn thèm thường tự qua.', 'Đổi hoạt động: đi bộ 5–10 phút, đánh răng, nhai kẹo cao su không đường.', 'Môi trường: không để snack trong tầm mắt/tầm tay; mua gói nhỏ; chia sẵn khẩu phần.', 'Lên kế hoạch món mình thích vào phần 20% thay vì cấm tuyệt đối (cấm càng thèm).', 'Kiểm tra HALT: Đói (Hungry), Bực (Angry), Cô đơn (Lonely), Mệt (Tired) – 3 cái sau không giải quyết bằng ăn.'] },
  { id: 20, section: 'habit', title: 'Vì sao giảm cân không có nghĩa là ăn khổ, không được ăn ngon', evidence: 'medium', points: ['Kết quả lâu dài phụ thuộc vào việc duy trì được bao lâu, không phải siết mạnh bao nhiêu. Chế độ khổ sở thường bỏ cuộc sau vài tuần rồi tăng lại.', 'Ngon không cần nhiều dầu/đường: dùng gia vị, rau thơm, tỏi, gừng, sả, ớt, chanh, tiêu, nướng bằng nồi chiên không dầu, hấp, áp chảo dầu xịt.', 'Hầu hết món yêu thích đều có phiên bản nhẹ hơn: phở ít bánh nhiều thịt nạc + rau, không húp hết nước; bún chả nhiều rau, ít bún; cơm tấm sườn bỏ mỡ, ít cơm.', 'Quy tắc 80/20: 80% ăn sạch có kế hoạch, 20% linh hoạt cho gia đình, đám giỗ, hẹn hò – vẫn đạt mục tiêu nếu trung bình tuần đúng.'] },
  { id: 21, section: 'habit', title: 'Tích nước: nguyên nhân, mức độ, cách nhận biết và xử lý', evidence: 'strong', points: ['Tích nước là phần cân nặng do nước giữ lại trong mô/mạch máu, không phải mỡ. Ở người > 100 kg có thể dao động 1–3 kg trong vài ngày.', 'Nguyên nhân chính: (1) Natri cao – thận giữ nước để pha loãng muối; (2) Tinh bột nhiều – mỗi 1 g glycogen giữ ~3 g nước; (3) Cortisol cao do stress/thiếu ngủ; (4) Viêm sau tập nặng hoặc khớp đang viêm; (5) Rượu bia (ban đầu lợi tiểu, sau đó cơ thể giữ nước bù); (6) Ít nước (cơ thể \'tiết kiệm\' nước); (7) Thức ăn chưa tiêu hóa, táo bón; (8) Thời tiết nóng, ngồi lâu; một số thuốc.', 'Mức độ (so với đường mỡ dự kiến trong Phân tích → Tổng quan): Đang xả nước < −0.5 kg; Bình thường −0.5 đến +0.5 kg; Tích nước vừa +0.5 đến +1.5 kg; Tích nước cao > +1.5 kg.', 'Dấu hiệu: cân tăng > 0.5 kg qua 1 đêm sau bữa mặn; nhẫn/giày chật; ấn vào mu bàn chân/cẳng chân để lại vết lõm; mặt, mí mắt sưng buổi sáng.', 'Xử lý: quay về natri ≤ 2,000 mg; uống đủ nước (đừng nhịn nước); tăng kali (rau xanh, khoai lang, chuối, nước dừa, sữa chua); đi bộ; ngủ đủ; thường hết sau 2–4 ngày.', 'Cần đi khám nếu: phù tăng dần, phù một bên chân kèm đau, khó thở, phù không giảm dù đã ăn nhạt.'] },
  { id: 22, section: 'habit', title: 'Tư duy Kaizen: cải thiện từng chút một', evidence: 'medium', points: ['Kaizen = thay đổi rất nhỏ, đều đặn, đo được. Mỗi lần chỉ sửa MỘT điểm yếu lớn nhất, giữ nó đến khi thành thói quen (≥ 5/7 ngày trong 2 tuần) rồi mới thêm điểm tiếp theo.', 'Lý do hiệu quả: thay đổi nhỏ không gây stress, não không \'chống đối\'; mỗi thành công nhỏ tạo động lực; thói quen cộng dồn theo thời gian.', 'Chu trình PDCA (quen thuộc với quản lý dự án): Plan – chọn 1 việc từ cột \'Kaizen\' ở Phân tích → Tuần/tháng; Do – làm trong 7 ngày; Check – xem điểm tuần và chỉ số đó; Act – giữ, chỉnh hoặc đổi cách.', 'Đo hệ thống, không đo một ngày: một ngày tiệc không phải thất bại; trung bình tuần mới là KPI.', 'Thất bại là dữ liệu: ngày không đạt cho biết tình huống nào cần kịch bản (tiệc, ăn ngoài, mệt, ngủ muộn).'] },
  { id: 23, section: 'habit', title: 'Đọc nhãn dinh dưỡng: kiểm soát muối và đường trong đồ đóng gói', evidence: 'strong', points: ['Luôn xem cột \'trên 100 g\' (khẩu phần ghi trên nhãn thường rất nhỏ để số trông thấp).', 'Natri /100 g: ≤ 120 mg = ít muối; 120–600 mg = vừa; > 600 mg = mặn.', 'Nhãn ghi \'muối\' (g) thay vì natri: natri (mg) = muối (g) × 400.', 'Đường /100 g: ≤ 5 g = ít; 5–22.5 g = vừa; > 22.5 g = nhiều.', 'Bảng thành phần xếp theo khối lượng giảm dần: đường, siro, mạch nha, maltodextrin nằm trong 3 thành phần đầu → là đồ ngọt dù quảng cáo \'ăn kiêng\'.', '\'Ít béo\', \'ăn kiêng\', \'healthy\', \'high protein\' không có nghĩa là ít muối – nhiều loại bù vị bằng muối, bột ngọt.', 'Quy tắc ăn vặt: mỗi lần ≤ 200 mg natri (~10% trần ngày) và ≤ 5 g đường.'] },
  { id: 24, section: 'habit', title: 'Nước ngọt 0 kcal (chất tạo ngọt)', evidence: 'medium', points: ['Chất tạo ngọt (aspartame, sucralose, stevia…) không chứa fructose nên không làm tăng axit uric như nước ngọt thường – với gout là lựa chọn tốt hơn hẳn.', 'Gần như 0 kcal nên không ảnh hưởng thâm hụt.', 'Lưu ý: ở một số người, vị ngọt thường xuyên duy trì thói quen thèm ngọt; nước có ga vẫn có thể gây đầy hơi.', 'Cách dùng hợp lý: thay thế nước ngọt có đường, xen kẽ với nước có ga không đường + chanh, không dùng thay cho nước lọc.'] },
  { id: 25, section: 'gout', title: 'Vì sao cần cân bằng giữa giảm mỡ và thải axit uric', evidence: 'strong', points: ['Giảm cân về lâu dài làm GIẢM axit uric và giảm số cơn gout – đây là mục tiêu đúng.', 'Nhưng giảm quá nhanh, nhịn ăn, bỏ bữa hay ăn rất ít (kiểu dưới ~1,200 kcal/ngày) làm cơ thể tạo thể ceton; ceton cạnh tranh với axit uric ở thận → thận thải uric kém đi → uric trong máu tăng TẠM THỜI, dễ khởi phát cơn gout.', 'Mất nước, rượu bia (đặc biệt bia), đường fructose, bữa purine rất cao cùng lúc với thâm hụt sâu là tổ hợp rủi ro nhất.', 'Giai đoạn mới dùng thuốc hạ uric (như febuxostat) cũng có thể có cơn gout khi tinh thể urat cũ tan ra – vì vậy bác sĩ thường cho kèm colchicine. Không tự ý dừng thuốc.', 'Nguyên tắc: thâm hụt vừa phải và đều, không nhịn bữa, uống đủ nước, rải purine đều các bữa thay vì dồn một bữa.'] },
  { id: 26, section: 'gout', title: 'Bài tập phù hợp với đầu gối và người bị gout', evidence: 'strong', points: ['Ưu tiên ít va đập: đi bộ (đường bằng, giày đệm tốt), đạp xe tại chỗ, bơi/đi bộ dưới nước – cơ khớp được vận động mà lực dồn lên gối thấp.', 'Tập sức mạnh để bảo vệ khớp: cơ đùi trước, mông khỏe giúp giảm tải cho gối. Bài an toàn: cầu mông, squat ngồi xuống ghế, ngồi dựa tường góc nông, nâng chân thẳng khi nằm, kéo dây kháng lực, push-up tựa tường.', 'Hạn chế khi gối yếu/đau: squat sâu, lunge, nhảy (jumping jack, burpee), chạy, leo dốc quá cao, đi xuống cầu thang nhiều.', 'Khi khớp đang sưng, nóng, đỏ (cơn gout cấp): nghỉ khớp đó, chườm lạnh, kê cao; chỉ vận động nhẹ phần cơ thể không đau. Tập lại từ từ khi hết sưng.', 'Khởi động 5–10 phút, uống nước trước – trong – sau tập (vận động mạnh + mất nước làm uric tăng). Đau nhói tại khớp là tín hiệu dừng.', 'Mỗi 1 kg giảm được làm giảm đáng kể lực dồn lên gối ở mỗi bước đi (khoảng vài kg lực) – giảm cân chính là \'bài tập\' tốt nhất cho gối.'] },
];
